-- ── THE MEASURE. The server never takes a client's word for a distance. ────────────────────────
create or replace function voyage.path_nm(p_path jsonb)
returns numeric
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  -- The polyline's own great-circle length, segment by segment, via THE distance authority
  -- (voyage.gc_distance_nm, 0002). A path is [[lat, lon], …]; anything shorter than two points
  -- measures 0 and the refusal function is what rejects it as a shape.
  select coalesce(sum(voyage.gc_distance_nm(
           (a.value->>0)::float8, (a.value->>1)::float8,
           (b.value->>0)::float8, (b.value->>1)::float8)), 0)
    from jsonb_array_elements(p_path) with ordinality a(value, i)
    join jsonb_array_elements(p_path) with ordinality b(value, i) on b.i = a.i + 1
$$;

revoke all on function voyage.path_nm(jsonb) from public, anon, authenticated;

-- ── THE LAW. A polyline is legal exactly when every sample of it is sailable water. ────────────
create or replace function voyage.path_refusal(
  p_path jsonb,
  p_from_lat numeric, p_from_lon numeric,
  p_to_lat   numeric, p_to_lon   numeric,
  p_join_nm  numeric,      -- how far path[first]/path[last] may sit from the stated ends
  p_head_nm  numeric,      -- measured approach allowance at the origin (its snap + one cell)
  p_tail_nm  numeric       -- measured approach allowance at the destination
)
returns text
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
-- Returns NULL for legal water, else the exact 'E_CODE: sentence' the mover raises. ONE reading
-- of "may a ship be here", shared by cmd.do_sail, cmd.divert and the land-guard proof — a second
-- sampler with a different step or allowance could disagree, which is the spaghetti this file
-- exists to prevent.
--
-- THE SAMPLING RULE: each segment is walked at half-cell steps (≤ 7.5 nm), linearly in
-- lat/lon — the SAME interpolation voyage.position uses to place the ship, so the line judged
-- is the line sailed. Samples inside the head/tail allowance of the path's FIRST/LAST point are
-- exempt: a harbour sits ON the coast and its cell is usually land at this resolution; the
-- allowance is the MEASURED snap of that harbour (sea_reaches.snap_nm), never a fixed guess.
-- A segment jumping the antimeridian the long way (|Δlon| > 180) is refused: the pathfinder
-- never emits one, and linear interpolation across it would sample water it does not cross.
declare
  r        public.sea_raster%rowtype;
  v_n      int;
  v_prev   jsonb := null;
  v_seg    jsonb;
  v_i      int := 0;
  v_lat1   float8; v_lon1 float8; v_lat2 float8; v_lon2 float8;
  v_nm     float8;
  v_step   int;
  v_s      int;
  v_f      float8;
  v_lat    float8; v_lon float8;
  v_row    int; v_col int;
  v_done   float8 := 0;
  v_total  float8;
begin
  if p_path is null or jsonb_typeof(p_path) <> 'array' or jsonb_array_length(p_path) < 2 then
    return 'E_BAD_PATH: a course is a list of at least two [lat, lon] points';
  end if;
  select * into r from public.sea_raster where id = 1;
  v_n := jsonb_array_length(p_path);

  -- Every point is a finite coordinate on the sphere.
  for v_i in 0 .. v_n - 1 loop
    v_seg := p_path->v_i;
    if jsonb_typeof(v_seg) <> 'array' or jsonb_array_length(v_seg) <> 2
       or jsonb_typeof(v_seg->0) <> 'number' or jsonb_typeof(v_seg->1) <> 'number' then
      return 'E_BAD_PATH: point ' || v_i || ' is not a [lat, lon] pair';
    end if;
    if abs((v_seg->>0)::float8) > 90 or abs((v_seg->>1)::float8) > 180 then
      return 'E_BAD_PATH: point ' || v_i || ' is off the sphere';
    end if;
  end loop;

  -- The course must JOIN what it claims to join: its first point at the stated origin, its last
  -- at the stated destination, within p_join_nm. Without this a legal-water path from anywhere
  -- to anywhere could be attached to any order.
  if voyage.gc_distance_nm(p_from_lat::float8, p_from_lon::float8,
                           (p_path->0->>0)::float8, (p_path->0->>1)::float8) > p_join_nm then
    return format('E_OFF_COURSE: the course begins %s nm from where she lies',
      round(voyage.gc_distance_nm(p_from_lat::float8, p_from_lon::float8,
                                  (p_path->0->>0)::float8, (p_path->0->>1)::float8)::numeric, 1));
  end if;
  if voyage.gc_distance_nm(p_to_lat::float8, p_to_lon::float8,
                           (p_path->(v_n-1)->>0)::float8, (p_path->(v_n-1)->>1)::float8) > p_join_nm then
    return format('E_OFF_COURSE: the course ends %s nm short of the destination',
      round(voyage.gc_distance_nm(p_to_lat::float8, p_to_lon::float8,
                                  (p_path->(v_n-1)->>0)::float8, (p_path->(v_n-1)->>1)::float8)::numeric, 1));
  end if;

  v_total := voyage.path_nm(p_path)::float8;
  if v_total <= 0 then
    return 'E_BAD_PATH: the course has no length';
  end if;

  -- Sample every segment. v_done tracks nm already walked, so the head/tail allowances are
  -- against the whole path's ends, exactly as the client's own straightener applies them.
  for v_i in 0 .. v_n - 2 loop
    v_lat1 := (p_path->v_i->>0)::float8;     v_lon1 := (p_path->v_i->>1)::float8;
    v_lat2 := (p_path->(v_i+1)->>0)::float8; v_lon2 := (p_path->(v_i+1)->>1)::float8;
    if abs(v_lon2 - v_lon1) > 180 then
      return format('E_BAD_PATH: segment %s jumps the antimeridian the long way round', v_i);
    end if;
    v_nm := voyage.gc_distance_nm(v_lat1, v_lon1, v_lat2, v_lon2)::float8;
    v_step := greatest(2, ceil(v_nm / 7.50)::int);
    for v_s in 1 .. v_step - 1 loop
      v_f := v_s::float8 / v_step;
      -- exempt only the measured approaches at the path's own two ends
      continue when v_done + v_f * v_nm < p_head_nm;
      continue when v_total - (v_done + v_f * v_nm) < p_tail_nm;
      v_lat := v_lat1 + (v_lat2 - v_lat1) * v_f;
      v_lon := v_lon1 + (v_lon2 - v_lon1) * v_f;
      v_row := least(719, greatest(0, floor((90 - v_lat) / 0.25)::int));
      v_col := ((floor((v_lon + 180) / 0.25)::int % 1440) + 1440) % 1440;
      if get_bit(r.cells, (v_row * 1440 + v_col) * r.bits_per_cell) = 0 then
        return format('E_LAND: the course touches land near %s°, %s° (segment %s)',
                      round(v_lat::numeric, 2), round(v_lon::numeric, 2), v_i);
      end if;
    end loop;
    v_done := v_done + v_nm;
  end loop;
  return null;
end $$;

revoke all on function voyage.path_refusal(jsonb, numeric, numeric, numeric, numeric, numeric, numeric, numeric) from public, anon, authenticated;

comment on function voyage.path_refusal(jsonb, numeric, numeric, numeric, numeric, numeric, numeric, numeric) is
  'THE water-legality of a proposed course (0046): shape, endpoint joins, and every segment '
  'sampled at half-cell intervals against public.sea_raster. NULL means legal water; anything '
  'else is the E_ sentence the mover raises. One sampler for do_sail, divert and the land guard.';

comment on function voyage.path_nm(jsonb) is
  'THE measure of a course (0046): the polyline''s own great-circle length. The server never '
  'takes a client''s word for a distance — it measures.';

-- ── SELF-ASSERT ────────────────────────────────────────────────────────────────────────────────
do $$
declare
  r          public.sea_raster%rowtype;
  v_n        int;
  v_bad      int;
  v_ports    int;
  v_nm       numeric;
  v_ref      text;
  v_lis_cad  constant jsonb := '[[38.71,-9.14],[36.875,-9.125],[36.625,-8.875],[36.53,-6.3]]'::jsonb;
begin
  -- (a) THE RASTER IS THERE AND THE BIT ORDER IS THE ONE THE CLIENT PACKS. Eight control cells,
  --     each a named piece of the world, asserted through get_bit — the same read the sampler
  --     uses. A packing that shifted one bit would fail all eight.
  select * into r from public.sea_raster where id = 1;
  if r.cols <> 1440 or r.rows <> 720 or r.bits_per_cell <> 2 or octet_length(r.cells) <> 259200 then
    raise exception '0046 self-assert FAIL: the raster is % x % at % bit(s) with % bytes — expected 1440 x 720 at 2 with 259200', r.cols, r.rows, r.bits_per_cell, octet_length(r.cells);
  end if;
  if get_bit(r.cells, 692320) <> 1 then
    raise exception '0046 self-assert FAIL: the mid-Atlantic (30, -40) reads %, expected 1', get_bit(r.cells, 692320);
  end if;
  if get_bit(r.cells, 583164) <> 0 then
    raise exception '0046 self-assert FAIL: the middle of Iberia (39.5, -4.5) reads %, expected 0', get_bit(r.cells, 583164);
  end if;
  if get_bit(r.cells, 566152) <> 1 then
    raise exception '0046 self-assert FAIL: the Bosphorus channel (41, 29) reads %, expected 1', get_bit(r.cells, 566152);
  end if;
  if get_bit(r.cells, 175200) <> 0 then
    raise exception '0046 self-assert FAIL: the Siberian arctic (ice) (75, 120) reads %, expected 0', get_bit(r.cells, 175200);
  end if;
  if get_bit(r.cells, 232160) <> 1 then
    raise exception '0046 self-assert FAIL: the Barents Sea (open — the Muscovy road) (70, 40) reads %, expected 1', get_bit(r.cells, 232160);
  end if;
  if get_bit(r.cells, 1787040) <> 0 then
    raise exception '0046 self-assert FAIL: the Antarctic pack (-65, 0) reads %, expected 0', get_bit(r.cells, 1787040);
  end if;
  if get_bit(r.cells, 900896) <> 1 then
    raise exception '0046 self-assert FAIL: the South China Sea (12, 112) reads %, expected 1', get_bit(r.cells, 900896);
  end if;
  if get_bit(r.cells, 773360) <> 0 then
    raise exception '0046 self-assert FAIL: the Sahara (23, 10) reads %, expected 0', get_bit(r.cells, 773360);
  end if;
  if get_bit(r.cells, 232161) <> 1 then
    raise exception '0046 self-assert FAIL: the Barents Sea does not carry the POLAR mark';
  end if;
  if get_bit(r.cells, 692321) <> 0 then
    raise exception '0046 self-assert FAIL: the mid-Atlantic carries a POLAR mark it must not';
  end if;
  if get_bit(r.cells, 1700121) <> 1 or get_bit(r.cells, 1700120) <> 1 then
    raise exception '0046 self-assert FAIL: the Drake Passage fringe should be open POLAR water';
  end if;

  -- (a2) THE TWO RASTERS AGREE AT THE CONTROLS: every sailable control cell answers a sea
  --      through voyage.sea_at (0040) — one authority composed, so a database where the
  --      membership and passability rasters drifted apart cannot apply this file.
  if voyage.sea_at(30, -40) is null then
    raise exception '0046 self-assert FAIL: the mid-Atlantic (30, -40) is sailable here but answers NO sea through voyage.sea_at (0040) — the two rasters have drifted apart';
  end if;
  if voyage.sea_at(41, 29) is null then
    raise exception '0046 self-assert FAIL: the Bosphorus channel (41, 29) is sailable here but answers NO sea through voyage.sea_at (0040) — the two rasters have drifted apart';
  end if;
  if voyage.sea_at(70, 40) is null then
    raise exception '0046 self-assert FAIL: the Barents Sea (70, 40) is sailable here but answers NO sea through voyage.sea_at (0040) — the two rasters have drifted apart';
  end if;
  if voyage.sea_at(12, 112) is null then
    raise exception '0046 self-assert FAIL: the South China Sea (12, 112) is sailable here but answers NO sea through voyage.sea_at (0040) — the two rasters have drifted apart';
  end if;

  -- (b) EVERY PLACE HAS A REACH ROW, AND EVERY ROW REACHES EVERY OTHER PLACE. Non-vacuous by
  --     the counts themselves: the world cannot hold an island nobody can sail to.
  select count(*) into v_ports from public.ports;
  select count(*) into v_n from public.sea_reaches;
  if v_n <> v_ports or v_n < 2 then
    raise exception '0046 self-assert FAIL: % reach row(s) for % port(s)', v_n, v_ports;
  end if;
  select count(*) into v_bad from public.sea_reaches sr
   where (select count(*) from jsonb_object_keys(sr.reaches)) <> v_ports - 1;
  if v_bad <> 0 then
    raise exception '0046 self-assert FAIL: % place(s) do not reach every other place', v_bad;
  end if;

  -- (c) THE TABLE IS SYMMETRIC — the whole crosswalk, not a sample. a→b and b→a are one flood,
  --     mirrored at generation; a divergence would mean two authorities for one distance.
  select count(*) into v_bad
    from public.sea_reaches a
   cross join lateral jsonb_each_text(a.reaches) e(code, nm)
    join public.sea_reaches b on b.code = e.code
   where (b.reaches->>a.code)::numeric is distinct from e.nm::numeric;
  if v_bad <> 0 then
    raise exception '0046 self-assert FAIL: % asymmetric pair reading(s)', v_bad;
  end if;

  -- (d) NO SAILED DISTANCE IS SHORTER THAN THE GREAT CIRCLE. The whole table against the one
  --     distance authority (0002), with a half-percent tolerance for the endpoint snap.
  select count(*) into v_bad
    from public.sea_reaches a
   cross join lateral jsonb_each_text(a.reaches) e(code, nm)
    join public.ports pa on pa.id = a.port_id
    join public.ports pb on pb.code = e.code
   where a.code < e.code
     and e.nm::numeric < voyage.gc_distance_nm(pa.lat::float8, pa.lon::float8, pb.lat::float8, pb.lon::float8) * 0.995;
  if v_bad <> 0 then
    raise exception '0046 self-assert FAIL: % pair(s) sail shorter than the great circle', v_bad;
  end if;

  -- (e) THE ARCTIC FIX AND THE CANAL CONTROLS — the three worldly facts this migration exists
  --     to make true, asserted as RULES about the served numbers, not as seeds.
  v_nm := (select (reaches->>'NAG')::numeric from public.sea_reaches where code = 'LIS');
  if v_nm is null or v_nm < 12000 then
    raise exception '0046 self-assert FAIL: LIS→NAG is % nm — under 12,000 means the Arctic is open again (the leg graph served 7,565 over the pole)', v_nm;
  end if;
  if (select (reaches->>'ADE')::numeric from public.sea_reaches where code = 'ALE') < 9000 then
    raise exception '0046 self-assert FAIL: ALE→ADE under 9,000 nm — a Suez Canal three centuries early';
  end if;
  if (select (reaches->>'ACA')::numeric from public.sea_reaches where code = 'VER') < 9000 then
    raise exception '0046 self-assert FAIL: VER→ACA under 9,000 nm — a Panama Canal three centuries early';
  end if;

  -- (f) THE MEASURE: a real proposed course (Lisbon→Cádiz round Cape St Vincent, produced by
  --     the one pathfinder at generation time) measures what the table says it measures, and
  --     LONGER than the straight line — the cape is the whole point.
  v_nm := voyage.path_nm(v_lis_cad);
  if abs(v_nm - 253.7) > 1.3 then
    raise exception '0046 self-assert FAIL: the embedded Lisbon→Cádiz course measures % nm, generation measured 253.7', v_nm;
  end if;
  if v_nm <= voyage.gc_distance_nm(38.71, -9.14, 36.53, -6.3) then
    raise exception '0046 self-assert FAIL: the sailed Lisbon→Cádiz course is not longer than the straight line — Cape St Vincent has gone missing';
  end if;

  -- (g) THE LAW, both ways — the positive control FIRST: the real water course is accepted…
  v_ref := voyage.path_refusal(v_lis_cad, 38.71, -9.14, 36.53, -6.3, 15,
             (select snap_nm from public.sea_reaches where code = 'LIS') + 25,
             (select snap_nm from public.sea_reaches where code = 'CAD') + 25);
  if v_ref is not null then
    raise exception '0046 self-assert FAIL: the real Lisbon→Cádiz water course was refused: %', v_ref;
  end if;
  -- …and the straight line Lisbon→Barcelona, which crosses the whole of Iberia, is REFUSED as
  -- land. This is the non-vacuity proof the never-touch-land law demands (OWNER_REQUESTS 41):
  -- a sampler that cannot catch a line across a continent is decoration.
  v_ref := voyage.path_refusal(
             jsonb_build_array(jsonb_build_array(38.71, -9.14), jsonb_build_array(41.38, 2.18)),
             38.71, -9.14, 41.38, 2.18, 15, 40, 40);
  if v_ref is null or v_ref not like 'E_LAND:%' then
    raise exception '0046 self-assert FAIL: a straight Lisbon→Barcelona line across Iberia was NOT refused as land (got [%])', coalesce(v_ref, 'null');
  end if;
  -- a course that joins the wrong ends is refused as itself, not as land
  v_ref := voyage.path_refusal(v_lis_cad, 36.53, -6.3, 38.71, -9.14, 15, 40, 40);
  if v_ref is null or v_ref not like 'E_OFF_COURSE:%' then
    raise exception '0046 self-assert FAIL: a course starting 250 nm from the stated origin was not refused E_OFF_COURSE (got [%])', coalesce(v_ref, 'null');
  end if;
  -- and a non-course is refused as a shape
  if voyage.path_refusal('[[1,2]]'::jsonb, 0, 0, 0, 0, 15, 0, 0) not like 'E_BAD_PATH:%' then
    raise exception '0046 self-assert FAIL: a one-point course was not refused E_BAD_PATH';
  end if;

  -- (h) the posture: world data readable, the two functions server-only
  if not has_table_privilege('authenticated', 'public.sea_reaches', 'select')
     or has_function_privilege('anon', 'voyage.path_refusal(jsonb, numeric, numeric, numeric, numeric, numeric, numeric, numeric)', 'execute')
     or has_function_privilege('authenticated', 'voyage.path_nm(jsonb)', 'execute')
     or (select count(*) from public.client_write_grants()) <> 0 then
    raise exception '0046 self-assert FAIL: the grant posture is wrong';
  end if;

  raise notice '0046 self-assert ok: the sea is one raster (1440x720, % bytes, 8 named control cells read back through get_bit), every one of % places reaches every other with a symmetric sailed distance never under the great circle; the Arctic is closed (LIS→NAG % nm where the leg graph served 7,565 over the pole) and there is no Suez and no Panama (ALE→ADE 11050 nm, VER→ACA 12398 nm); the measure prices the embedded Lisbon→Cádiz course at % nm (the straight line is %), the law accepted that course and REFUSED a straight Lisbon→Barcelona line across Iberia as E_LAND, a mis-joined course as E_OFF_COURSE and a one-point course as E_BAD_PATH; 0 client write grants',
    octet_length(r.cells), v_ports,
    (select (reaches->>'NAG')::numeric from public.sea_reaches where code = 'LIS'),
    round(voyage.path_nm(v_lis_cad), 1),
    round(voyage.gc_distance_nm(38.71, -9.14, 36.53, -6.3)::numeric, 1);
end $$;
